<script>
(() => {
'use strict';
const ns='http://www.w3.org/2000/svg';
const byId=id=>document.getElementById(id);
function draw(parent,tag,attrs){
  const node=document.createElementNS(ns,tag);
  for(const [key,value] of Object.entries(attrs)) node.setAttribute(key,value);
  parent.append(node);
  return node;
}
const group=(p,attrs={})=>draw(p,'g',attrs);
const path=(p,d,fill,attrs={})=>draw(p,'path',{d,fill,...attrs});
const line=(p,d,color,width,opacity=1)=>path(p,d,'none',{stroke:color,'stroke-width':width,'stroke-linecap':'round','stroke-linejoin':'round',opacity});
const dot=(p,cx,cy,rx,ry,fill,attrs={})=>draw(p,'ellipse',{cx,cy,rx,ry,fill,...attrs});
let seed=8493;
function random(){seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296}
const range=(a,b)=>a+(b-a)*random();
const pick=a=>a[Math.floor(random()*a.length)];
const f=n=>+n.toFixed(2);
const place=(x,y,angle=0,s=1)=>'translate('+x+' '+y+') rotate('+angle+') scale('+s+')';
function speckle(p,count,bounds,colors,lo,hi){
  const [x,y,w,h]=bounds;
  for(let i=0;i<count;i++){
    const px=range(x,x+w),py=range(y,y+h),r=range(lo,hi);
    dot(p,f(px),f(py),f(r),f(r*range(.27,.85)),pick(colors),{opacity:f(range(.28,.8))});
  }
}
// Broken horizontal marks pick up the light on the table.
for(let i=0;i<530;i++){
  const x=range(-190,1590),y=range(0,440),w=range(10,260);
  line(byId('wood'),\`M\${f(x)} \${f(y)}q\${f(w*.55)} \${f(range(-2,2))} \${f(w)} \${f(range(-1,1))}\`,pick(['#8e6a4e','#8b6150','#090e11']),range(.4,1.2),range(.035,.13));
}
const crock=byId('ceramic');
speckle(crock,1600,[140,394,720,240],['#8a9892','#516768','#0f2226','#bbab8c'],.3,1.45);
// Wrap the engraved semicircles around the curved wall of the bowl.
const wave=byId('waves');
function project(u,v){
  const a=u/373;
  const shrink=1-v*.0026;
  return [500+354*Math.sin(a)*shrink,363+144*Math.cos(a)+v*(.36+.68*Math.cos(a))];
}
const waveband=group(wave,{fill:'none',stroke:'#99aba0','stroke-width':1.55,opacity:.59});
for(let row=0;row<4;row++){
  let d='';
  for(let col=-13;col<=13;col++){
    const cx=col*54+(row%2)*27,cy=row*15+22;
    for(const r of [25.8,20.5,15.1,9.6,4.1]){
      const pts=[];
      for(let i=0;i<=18;i++){
        const a=Math.PI+i*Math.PI/18;
        const u=cx+r*Math.cos(a),v=cy+r*Math.sin(a);
        if(Math.abs(u)>541) continue;
        // The following row covers the lower corners of each fan.
        const offset=Math.abs(r*Math.cos(a));
        if(v>cy+15-Math.sqrt(Math.max(0,26*26-(27-offset)**2)))continue;
        pts.push(project(u,v).map(f).join(' '));
      }
      if(pts.length>1)d+='M'+pts.join('L');
    }
  }
  path(waveband,d,'none');
}
for(const v of [-7,-4,72,75]){
 let d='';for(let i=-538;i<=538;i+=4)d+=(d?'L':'M')+project(i,v).map(f).join(' ');
 line(wave,d,'#95a69b',v===-7||v===75?1.7:.85,.48);
}
const broth=byId('broth');
for(let i=0;i<370;i++){
  let x=range(155,849),y=range(235,476),r=range(.8,8);
  dot(broth,f(x),f(y),f(r),f(r*range(.25,.58)),pick(['#eaa64a','#e2a243','#93461e','#bb5420']),{opacity:f(range(.4,.88))});
  if(i%5===0)line(broth,\`M\${f(x-r)} \${f(y)}q1 -2 \${f(r)} -2\`,'#f6c473',1,.65);
}
// Independent strands converge and cross in loose folds near the front of the broth.
const pasta=byId('noodles');
function strand(d,t,highlight){
 line(pasta,d,'#94501e',t+3,.84);line(pasta,d,'#cc8c3f',t+1);line(pasta,d,highlight,t);
 const glint=line(pasta,d,'#ffe4a1',1.35,.73);glint.setAttribute('transform','translate(-.7 -1.6)');
}
function bundle(count,fn){for(let i=0;i<count;i++)strand(fn(i),range(4.8,6.4),pick(['#e7b75e','#edc272','#e7af55','#f0c678']));}
bundle(8,i=>\`M\${182+i*2} \${344+i*4} C238 \${288+i*5} 323 \${374+i*6} 399 \${322+i*5} S522 \${274+i*5} 583 \${305+i*4} S686 \${363+i*4} 767 \${300+i*5}\`);
bundle(7,i=>\`M\${207+i*2} \${363+i*4} C\${261+i*5} \${327+i*3} \${255+i*8} \${425+i*5} \${338+i*6} \${381+i*6} S\${430+i*4} \${329+i*2} \${490+i*3} \${344+i*5} S555 \${374+i*7} 626 \${324+i*5}\`);
bundle(6,i=>\`M\${295+i*3} \${437+i*3} C\${330+i*3} \${428+i*8} \${378+i*3} \${368+i*5} \${449+i*4} \${391+i*4} S\${538+i*6} \${448+i*4} \${601+i*5} \${391+i*4} S\${663+i*4} \${349+i*4} \${732+i*3} \${370+i*5}\`);
bundle(5,i=>\`M\${362+i*4} \${465+i*3} C\${395+i*4} \${437+i*5} \${418+i*6} \${420+i*3} \${469+i*5} \${429+i*5} S\${558+i*7} \${475+i*4} \${622+i*5} \${426+i*6} Q\${674+i*4} \${380+i*4} \${754+i*4} \${402+i*4}\`);
bundle(4,i=>\`M\${413+i*7} \${362+i*4} C\${469+i*2} \${320+i*3} \${511+i*4} \${315+i*3} \${558+i*4} \${337+i*4} C\${612+i*7} \${363+i*4} \${531+i*6} \${389+i*6} \${496+i*4} \${382+i*4} S\${446+i*2} \${353+i*3} \${416+i*5} \${374+i*6}\`);
function nori(x,y,a,s){
 const g=group(byId('seaweed'),{transform:place(x,y,a,s)});
 draw(g,'use',{href:'#sheet',fill:'url(#sea)',stroke:'#17251e','stroke-width':2.2});
 const texture=group(g,{'clip-path':'url(#noriClip)'});
 for(let i=0;i<870;i++){
   let xx=range(-55,54),yy=range(-80,65),w=range(1,7);
   line(texture,\`M\${f(xx)} \${f(yy)}l\${f(w*.4)} \${f(-w*.55)} \${f(w*.5)} \${f(w*.23)}\`,pick(['#687451','#172b23','#82906a','#101f1d','#52654c']),range(.55,2.8),range(.3,.72));
 }
 line(g,'M-52 -73 L-42 -75 -34 -73 -22 -76 -13 -74 -2 -76 6 -74 17 -76 27 -74 39 -76 49 -75','#889073',1.7,.8);
}
nori(564,252,-15,.91); nori(631,252,10,1.07); nori(687,275,24,.82);
function bok(x,y,a,s){
 const g=group(byId('greens'),{transform:place(x,y,a,s)});
 draw(g,'use',{href:'#leafShape',fill:'url(#leaf)',stroke:'#304a35','stroke-width':1.7});
 const texture=group(g,{'clip-path':'url(#leafClip)'});
 speckle(texture,230,[-65,-70,130,160],['#8a9e5e','#284d38','#658050'],.4,2.4);
 for(const side of [-1,1]){
   for(let i=0;i<6;i++){
     const base=-28+i*17,edge=side*(28+26*Math.sin(i*.66+.12));
     line(texture,\`M\${i*.85} \${base+14} Q\${edge*.53} \${base+1} \${edge} \${base-27}\`,'#96a767',2.3,.63);
     line(texture,\`M\${edge*.4} \${base+5} q\${edge*.17} -13 \${edge*.13} -20\`,'#93a76b',1.15,.5);
   }
 }
 path(g,'M-5 -49 C-1 -10 -1 27 -7 56 C-10 78 -10 108 -1 125 Q6 136 18 125 C24 114 15 86 12 66 C6 30 3 -10 -5 -49Z','url(#stalk)');
 line(g,'M-3 116 C-7 89 4 63 3 19','#d7d997',2.1,.65);
 line(g,'M13 116 Q11 93 8 81','#697f49',1.4,.7);
}
bok(342,247,-13,.84);bok(293,265,-32,1.02);bok(253,303,-58,.93);
function mushroom(x,y,a,s,scored){
 const g=group(byId('mushrooms'),{transform:place(x,y,a,s)});
 dot(g,2,22,67,24,'#522e1b',{opacity:.45,filter:'url(#shadow)'});
 draw(g,'use',{href:'#capShape',fill:'url(#cap)',stroke:'#593526','stroke-width':2});
 const texture=group(g,{'clip-path':'url(#capClip)'});
 speckle(texture,540,[-69,-49,140,93],['#e1ae79','#dda46b','#75432c','#583021'],.4,1.9);
 for(let i=0;i<29;i++){
   let xx=range(-64,63),yy=range(-35,32);
   line(texture,\`M\${f(xx)} \${f(yy)}q3 -2 8 -2\`,'#e1ab79',1.1,.4);
 }
 if(scored){
 path(g,'M-48 -13 Q-24 -11 -9 -8 Q-14 -17 -26 -30 Q-7 -22 3 -12 Q10 -22 23 -30 Q17 -17 14 -8 Q31 -7 48 -2 Q29 1 13 0 Q16 11 23 24 Q8 15 1 4 Q-14 11 -31 17 Q-21 6 -11 -1 Q-33 -4 -48 -13Z','#744528');
 path(g,'M-47 -15 Q-25 -13 -7 -9 Q-14 -20 -25 -32 Q-7 -24 4 -13 Q12 -24 24 -31 L14 -10 Q34 -10 49 -3 Q29 -2 12 -2 Q15 10 23 22 Q9 13 2 2 Q-12 9 -30 15 Q-19 4 -8 -3 Q-28 -7 -47 -15Z','url(#cut)');
 }else{
