 const gp=group(g);
 for(let i=0;i<27;i++){
 const t=i/26,xx=-61+124*t,yy=12-12*Math.sin(t*2);
 line(gp,\`M8 20 Q\${xx*.5} \${22+10*Math.sin(t*3.14)} \${xx} \${yy}\`,'#8d634b',1.6,.82);
